		'\t\tif (ms < 1) return (ms / 1000).toFixed(1) + "s";',
		'\t\treturn Math.floor(ms / 1000).toString() + "s";',
		'\t}',
		'',
		'\tlet days = Math.floor(ms / 86_400_000);',
		'\tlet hours = Math.floor((ms % 86_400_000) / 3_600_000);',
		'\tlet minutes = Math.floor((ms % 3_600_000) / 60_000);',
		'\tlet seconds = Math.round((ms % 60_000) / 1000);',
		'',
		'\tif (seconds === 60) {',
		'\t\tseconds = 0;',
		'\t\tminutes++;',
		'\t}',
